function frame(now){const dt=lastFrame?Math.min((now-lastFrame)/1000,1):0;lastFrame=now;if(!paused)visualTime+=dt;ctx.clearRect(0,0,960,520);if(!mission){drawHub();}else{if(!paused&&mission.phase==='playing'){for(let remaining=dt;remaining>0&&mission.phase==='playing';remaining-=1/30)tick(mission,Math.min(remaining,1/30),{left:keys.has('left'),right:keys.has('right'),up:keys.has('up'),down:keys.has('down'),action:keys.has('action')});}({solar:drawSolar,rover:drawRover,power:drawPower,shelter:drawShelter})[mission.id]();if(mission.phase==='playing'){$('#hudStatus').textContent=paused?tr("text346"):mission.id==='power'?tr("text347"):mission.id==='shelter'&&mission.elapsed>12?tr("text348"):tr("text349");$('#hudTime').textContent=mission.id==='power'?tr("text350", [mission.shift+1]):`${String(Math.floor(Math.ceil(mission.time)/60)).padStart(2,'0')}:${String(Math.ceil(mission.time)%60).padStart(2,'0')}`;if(mission.id!=='power')updateTelemetry();}if(mission.eventVersion!==seenEvent){seenEvent=mission.eventVersion;toast(mission.event);}if(mission.phase==='finished')showResult();}if(now>toastUntil)$('#sceneToast').classList.add('hidden');requestAnimationFrame(frame);}
